Q: Calculate a point on a bounding box based on angle A: <p>Recently I just provide an ans for this question in C#, <a href="https://stackoverflow.com/questions/51979673/how-to-get-random-points-from-a-box-collider2d/51980673#51980673">see also</a>.</p>

<p>Well, translate it into JS is not a difficult task.</p>

<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>var c=document.getElementById("myCanvas");


var rect = c.getBoundingClientRect();
var center = [rect.x + rect.width / 2.0, rect.y + rect.height/2.0]

function calCoor(theta, a, b)
{
    var rad = theta * Math.PI / 180.0;
    var x, y;
    var tan = Math.tan(rad);
    if (Math.abs(tan) &gt; b/ a)
    {
        x = tan &gt; 0 ? a : -a;
        y = b / tan;
    } else
    {
        x = a * tan;
        y = tan &lt; 0 ? b : -b;
    }
    return [x,y]
}
var angle = 90;
var random_post = calCoor(angle, rect.width / 2.0, rect.height/2.0)

console.log("Angle at: " + angle)
console.log("x at: " + (random_post[0] + center[0]))
console.log("y at: " + (random_post[1] + center[1]))</code></pre>
